import{z as n,x as o,o as B,c as p,q as l,j as t,D as e,d as s,s as A,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Berlekamp–Massey 递推识别","description":"","frontmatter":{"title":"Berlekamp–Massey 递推识别","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/berlekamp-massey.md","filePath":"cs/berlekamp-massey.md","lastUpdated":1791063341000}'),d={name:"cs/berlekamp-massey.md"};function m(C,a,D,F,k,h){const r=o("Mermaid");return B(),p("div",null,[a[2]||(a[2]=l('<h1 id="berlekamp–massey-递推识别" tabindex="-1">Berlekamp–Massey 递推识别 <a class="header-anchor" href="#berlekamp–massey-递推识别" aria-label="Permalink to &quot;Berlekamp–Massey 递推识别&quot;">​</a></h1><div class="epigraph"><p>给一段观测序列，最短的能生成它的线性递推是什么——Berlekamp–Massey 一遍扫描给出答案，答案的长度本身就是这条序列的线性复杂度。</p><footer>—— J. L. Massey, Shift-Register Synthesis and BCH Decoding, 1969</footer></div><p><a href="/cs/euler-tour-tree">上一课</a>伺候的树再怎么动，结构始终摆在明面；这一课反过来——只给序列，不给结构，问「哪条最短线性递推能生成它」。暴力算出前几十项、想外推到第 \\(10^{18}\\) 项，第一步就是把「猜递推」变成「算递推」。本课写 BM 算法，不写 BCH 译码的完整上下文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞赛与工程里的高频桥段：某个量跑程序能算出前 \\(40\\) 项，答案却要第 \\(10^{18}\\) 项。人眼找规律不可靠，枚举递推长度逐个解方程是 \\(O(k^3)\\) 的土办法。缺口：从序列到递推式的系统算法，还要能说清「找到的就是最短的」。本课不写：非线性规律的识别（多半无解）、BM 在编码译码中的完整流程。</p><p><span class="marginnote">数字实例：斐波那契 \\(0,1,1,2,3,5,8\\) 的递推是 \\(a_i=a_{i-1}+a_{i-2}\\)。BM 扫到第 \\(3\\) 项失配、把长度从 \\(1\\) 提到 \\(2\\)，此后一路零失配——\\(8\\) 个数够它锁定长度 \\(2\\)。</span></p><p><span class="marginnote">术语翻译：LFSR，线性反馈移位寄存器；BM 找的递推式与 LFSR 的反馈系数一一对应，「最短递推」即「最短能生成该序列的寄存器」，长度称线性复杂度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护当前递推 \\(C(x)\\)、上次失配时的备份 \\(B(x)\\) 与失配位置。逐位扫描：第 \\(i\\) 位算失配值——按当前递推预测该位，与真值作差。零失配就前进；非零失配时看长度够不够修：够，用 \\(B\\) 修正 \\(C\\) 的系数；不够，延长 \\(C\\)，并把修正前的 \\(C\\) 存进 \\(B\\)。</p>',9)),(B(),t(i,null,{default:e(()=>[A(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%80%90%E4%BD%8D%E8%AF%BB%E5%85%A5%E5%BA%8F%E5%88%97%22%5D%20--%3E%20B%5B%22%E6%8C%89%E5%BD%93%E5%89%8D%E9%80%92%E6%8E%A8%E7%AE%97%E6%9C%AC%E4%BD%8D%E9%A2%84%E6%B5%8B%E5%80%BC%22%5D%0A%20%20B%20--%3E%20C%7B%22%E9%A2%84%E6%B5%8B%E4%B8%8E%E7%9C%9F%E5%80%BC%E4%B8%80%E8%87%B4%E5%90%97%22%7D%0A%20%20C%20--%3E%7C%22%E4%B8%80%E8%87%B4%22%7C%20D%5B%22%E5%89%8D%E8%BF%9B%EF%BC%8C%E9%80%92%E6%8E%A8%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20C%20--%3E%7C%22%E5%A4%B1%E9%85%8D%22%7C%20E%7B%22%E5%BD%93%E5%89%8D%E9%95%BF%E5%BA%A6%E8%BF%98%E5%A4%9F%E4%BF%AE%E5%90%97%22%7D%0A%20%20E%20--%3E%7C%22%E5%A4%9F%22%7C%20F%5B%22%E7%94%A8%E5%A4%87%E4%BB%BD%20B%20%E4%BF%AE%E6%AD%A3%20C%20%E7%9A%84%E7%B3%BB%E6%95%B0%22%5D%0A%20%20E%20--%3E%7C%22%E4%B8%8D%E5%A4%9F%22%7C%20G%5B%22%E5%BB%B6%E9%95%BF%20C%EF%BC%8C%E5%B9%B6%E6%8A%8A%E6%97%A7%20C%20%E5%AD%98%E4%B8%BA%20B%22%5D%0A%20%20F%20--%3E%20D%0A%20%20G%20--%3E%20D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"一遍扫描 \\(O(k^2)\\)，\\(k\\) 取几十到几千都在毫秒级。实现难点全在「备份时机」：存晚了，\\(B\\) 里是修过的系数，修正公式当场作废。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像配一把最短的万能钥匙——齿太短开不动（递推短了压不住序列），太长白费料（塞满 \\(k-1\\) 个系数谁都能拟合有限项）。BM 的价值在于每一步都知道「最短」到底还没到。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"短，为什么可求：识别长度 \\(L\\) 的递推等价于解一组 Toeplitz 型线性方程，\\(2L\\) 个连续项唯一确定最短解；BM 不显式解方程，而是增量维护解、对上次失配做秩一修正，把复杂度从立方压到平方。线性复杂度就等于输出递推的长度，这条性质让它反过来当「规律是否线性」的体检器：递推长度随喂入项数稳定不再涨，才敢往下信。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"常见误区：把 BM 的输出当唯一真理。有限长序列永远存在无数条更长的递推与它相容；错在把「窗口内成立」当成「全局成立」。验证只有一条路：再多喂几项，失配就说明还没到头。")],-1)),(B(),t(i,null,{default:e(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E6%83%B3%E8%AF%86%E5%88%AB%E9%95%BF%E5%BA%A6%20L%20%E7%9A%84%E9%80%92%E6%8E%A8%22%5D%20--%3E%20N%5B%22%E8%87%B3%E5%B0%91%E9%9C%80%E8%A6%81%202L%20%E4%B8%AA%E8%BF%9E%E7%BB%AD%E9%A1%B9%22%5D%0A%20%20N%20--%3E%20OK%5B%22%E7%BB%99%E5%A4%9F%202L%20%E9%A1%B9%EF%BC%9A%E6%9C%80%E7%9F%AD%E8%A7%A3%E5%94%AF%E4%B8%80%EF%BC%8CBM%20%E7%A8%B3%E5%AE%9A%E6%94%B6%E6%95%9B%22%5D%0A%20%20N%20--%3E%20BAD%5B%22%E9%A1%B9%E6%95%B0%E4%B8%8D%E8%B6%B3%EF%BC%9A%E5%8F%AF%E8%83%BD%E6%8B%9F%E5%90%88%E5%87%BA%E5%81%87%E9%80%92%E6%8E%A8%22%5D%0A%20%20BAD%20--%3E%20W%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%E5%85%A8%E5%AF%B9%E3%80%81%E5%A4%96%E6%8E%A8%E5%BF%85%E9%94%99%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>只对线性规律有效——几何数列、矩阵幂特征值的组合、卷积结果的尾段全是线性递推，BM 都接得住；快速幂套取模复合这类非线性行为，BM 给出的只是数值巧合，别外推。域要挑对：模数为素数才谈得上除法与失配修正。BM 与下一课是上下游：BM 给出递推式，下一课的多项式取模负责拿这条式子算第 \\(k\\) 项——一个管「规律是什么」，一个管「第 \\(10^{18}\\) 项是多少」。</p><p><span class="marginnote">常见误区：只有 \\(3\\) 个观测项就敢拿长度 \\(2\\) 的递推外推——识别它至少要 \\(4\\) 项，\\(3\\lt 2L\\)，窗口锁不死规律，错在跳过了「项数至少两倍递推长」这条门槛。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BM 一遍 \\(O(k^2)\\) 扫描输出最短线性递推，长度即线性复杂度。</li><li>\\(2L\\) 项连续观测是识别长度 \\(L\\) 递推的门槛，短窗必出假解。</li><li>输出是「相容的最短解」，不是被证实的规律；加项验证不可省。</li><li>递推式到手后交给下一课的多项式取模去算远项。</li><li>出处：J. L. Massey, <em>Shift-Register Synthesis and BCH Decoding</em>, IEEE Trans. Inf. Theory, 1969；E. R. Berlekamp, <em>Algebraic Coding Theory</em>, 1968。</li></ul>',5))])}const M=n(d,[["render",m]]);export{f as __pageData,M as default};
